import os
from google.generativeai import GenerativeModel
import google.generativeai as genai


class GeminiClient:
    def __init__(self, api_key: str = None, model_name: str = "gemini-2.5-flash"):
        self.api_key = api_key or os.environ.get("GOOGLE_API_KEY")
        if not self.api_key:
            raise ValueError("Google API Key not provided and not found in GOOGLE_API_KEY environment variable.")
        genai.configure(api_key=self.api_key)
        self.model = GenerativeModel(model_name=model_name)

    def generate_content(self, prompt: str):
        response = self.model.generate_content(prompt)
        return response

    def stream_generate_content(self, prompt: str):
        responses = self.model.generate_content(prompt, stream=True)
        return responses

from typing import Dict, Any, List


class TextPayload:
    def __init__(self, text: str):
        self.text = text


class SummaryResult:
    def __init__(self, text: str):
        self.text = text


class JsonExtractionResult:
    def __init__(self, json_data: Dict[str, Any]):
        self.json_data = json_data


class AnswerWithContextPayload:
    def __init__(self, question: str, context: str):
        self.question = question
        self.context = context


class CompletionStreamResult:
    def __init__(self, tokens: List[str]):
        self.tokens = tokens

from model_client import GeminiClient
from model_models import JsonExtractionResult

def extract_json(payload: dict, config: dict = None) -> JsonExtractionResult:
    config = config or {}
    client = GeminiClient(api_key=config.get("api_key"), model_name="gemini-2.5-flash")
    prompt = (
        "Extract structured JSON from the following text. "
        "Ensure the output is a valid JSON object. Text:\n\n" + payload["text"]
    )
    response = client.generate_content(prompt)
    try:
        # Attempt to parse the response text as JSON. Assume the model outputs raw JSON.
        import json
        json_data = json.loads(response.text.strip())
        return JsonExtractionResult(json_data=json_data)
    except json.JSONDecodeError:
        # If the model doesn't output perfect JSON, try to find a JSON block
        import re
        match = re.search(r"```json\n(.*)\n```", response.text, re.DOTALL)
        if match:
            try:
                json_data = json.loads(match.group(1))
                return JsonExtractionResult(json_data=json_data)
            except json.JSONDecodeError:
                pass
        return JsonExtractionResult(json_data={})

from model_client import GeminiClient
from model_models import AnswerWithContextPayload, SummaryResult

def answer_with_context(payload: AnswerWithContextPayload, config: dict = None) -> SummaryResult:
    config = config or {}
    client = GeminiClient(api_key=config.get("api_key"), model_name="gemini-2.5-flash")
    prompt = (
        f"Using the following context, answer the question. "
        f"Context: {payload.context}\n\nQuestion: {payload.question}"
    )
    response = client.generate_content(prompt)
    return SummaryResult(text=response.text or "")

from model_client import GeminiClient
from model_models import TextPayload, CompletionStreamResult

def stream_completion(payload: TextPayload, config: dict = None) -> CompletionStreamResult:
    config = config or {}
    client = GeminiClient(api_key=config.get("api_key"), model_name="gemini-2.5-flash")
    prompt = "Continue the following text:\n\n" + payload.text
    responses = client.stream_generate_content(prompt)
    tokens = []
    for chunk in responses:
        tokens.append(chunk.text)
    return CompletionStreamResult(tokens=tokens)

import os
from google.cloud import translate_v2 as translate

def translate_text(text: str, target_language: str, config: dict = None) -> dict:
    config = config or {}
    # Google Cloud Translation API client does not require explicit project_id if GOOGLE_APPLICATION_CREDENTIALS is set
    # or running in a Google Cloud environment.
    translate_client = translate.Client()

    response = translate_client.translate(text, target_language=target_language)

    return {
        "translated_text": response["translatedText"],
        "original_text": response["input"],
        "detected_source_language": response["detectedSourceLanguage"],
    }

import os
from typing import List, Dict, Any
from google.cloud import aiplatform

def get_embedding(text_content: str, config: dict = None) -> Dict[str, Any]:
    config = config or {}
    project_id = config.get("project_id") or os.environ.get("GOOGLE_CLOUD_PROJECT")
    location = config.get("location") or "us-central1"

    if not project_id:
        raise ValueError("Google Cloud Project ID not provided and not found in GOOGLE_CLOUD_PROJECT environment variable.")

    aiplatform.init(project=project_id, location=location)

    # The embedding model to use. Text embeddings are available under the `textembedding-gecko` family.
    # The specific model ID might vary, so using a common one here.
    # For the latest model IDs, refer to Vertex AI documentation.
    model_name = "textembedding-gecko@003"

    # Initialize the TextEmbeddingModel
    model = aiplatform.gapic.PredictionServiceClient(
        client_options={"api_endpoint": f"{location}-aiplatform.googleapis.com"}
    ).get_model_full_name(project=project_id, location=location, model=model_name)

    # Prepare the instance for embedding
    instances = aiplatform.gapic.accelerator_type.EmbeddingData(
        text=text_content
    ).to_json()

    # In a real scenario, you would create a list of instances for batch prediction.
    # For a single text, we still wrap it in a list.
    instances_list = [instances]

    # Predict embeddings
    try:
        response = aiplatform.gapic.PredictionServiceClient(
            client_options={"api_endpoint": f"{location}-aiplatform.googleapis.com"}
        ).predict(
            endpoint=f"projects/{project_id}/locations/{location}/publishers/google/models/{model_name}",
            instances=instances_list,
        )

        # Parse the response to get the embedding vector
        embeddings = []
        for prediction in response.predictions:
            # The embedding is typically nested in a structure like this based on the model output format
            if "embeddings" in prediction and "values" in prediction["embeddings"]:
                embeddings.append(list(prediction["embeddings"]["values"]))
            elif "embedding" in prediction and "values" in prediction["embedding"]:
                 embeddings.append(list(prediction["embedding"]["values"]))
            else: # Fallback for unexpected structure or direct value
                embeddings.append(list(prediction))

        return {"embedding": embeddings[0] if embeddings else []}

    except Exception as e:
        # Handle cases where the model response structure is different or an error occurs
        print(f"Error getting embedding: {e}")
        return {"embedding": []}
